# -*- coding: utf-8 -*-
"""Grade 1–2 learning topics. Questions are generated by primary_qgen."""
from primary_qgen import add4, sub4, mul4, div4, calc, story, fact, ask, rem, choice_num, expr4

NA, GG, SP, IP = "Numbers and Algebra", "Shapes and Geometry", "Statistics and Probability", "Integrated Practice"
TOPICS = []


# "上" and "下" are parser-required semester tokens in the generated topic data.
def U(grade, sem, n, uname, ip=False):
    def add(slug, name, dom, typ, desc, mc, std, pre, qs, root=None):
        TOPICS.append({
            "slug": slug, "name": name, "domain": dom, "grade": grade, "semester": sem,
            "unit": n, "uname": uname, "ip": ip, "type": typ, "description": desc,
            "mastery_criteria": mc, "standards": std, "pre": pre, "qs": qs,
            "root_reason": root,
        })
    return add


def S(*codes):
    """'1.NA.01' is exact; (code, note) is inferred."""
    return list(codes)


